H.background();
const v = H.plot2d({ xMin: -2, xMax: 12, yMin: -4, yMax: 8 });
v.grid(); v.axes();
const h = P.h, c = P.c, L = P.L;
const f = (x) => (x < h ? NaN : Math.sqrt(x - h) + c);
v.fn(f, { color: H.colors.accent, width: 3 });
v.line(-2, L, 12, L, { color: H.colors.violet, width: 2, dash: [5, 5] });
const rhs = L - c;
const hasSol = rhs >= 0;
const xsol = h + rhs * rhs;
if (hasSol && xsol <= 12) {
  const pulse = 6 + 2 * Math.sin(t * 3);
  v.circle(xsol, L, pulse, { fill: H.colors.good });
  v.line(xsol, -4, xsol, L, { color: H.colors.good, width: 1.2, dash: [3, 3] });
}
const xs = h + ((t * 1.5) % 10);
const ys = f(xs);
if (isFinite(ys) && ys < 8) v.dot(xs, ys, { r: 6, fill: H.colors.warn });
H.text("√(x − h) + c = L", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const msg = hasSol ? ("x = h + (L−c)² = " + xsol.toFixed(2)) : "L < c  →  NO solution (extraneous)";
H.text("h = " + h.toFixed(1) + "  c = " + c.toFixed(1) + "  L = " + L.toFixed(1) + "    " + msg, 24, 52, { color: hasSol ? H.colors.good : H.colors.warn, size: 13 });
H.legend([{ label: "√(x−h)+c", color: H.colors.accent }, { label: "y = L", color: H.colors.violet }], H.W - 160, 28);
